const CACHE = 'bvh-' + VERSION;

self.addEventListener('install', e => {
  // Lưu từng file một: một file lỗi mạng không làm hỏng cả lần cài (trước đây addAll lỗi là kẹt bản cũ).
  e.waitUntil(caches.open(CACHE).then(c => Promise.all(CORE.map(f => c.add(new Request(f, {cache: 'reload'})).catch(() => {}))))
    .then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    // Giữ lại hình/giọng đã tải ở bản cũ (tên file không đổi) để khỏi tải lại.
    const cache = await caches.open(CACHE);
    for (const k of await caches.keys()) {
      if (!k.startsWith('bvh-') || k === CACHE) continue;
      const old = await caches.open(k);
      for (const req of await old.keys()) {
        const u = new URL(req.url);
        if (/\/(img|audio|photo|sprites)\//.test(u.pathname)) {
          const want = REST.find(f => u.pathname.endsWith('/' + f.split('?')[0]));
          const r = want && await old.match(req);
          if (r) await cache.put(new Request(want), r);
        }
      }
      await caches.delete(k);
    }
    await self.clients.claim();
  })());
});

let warming = false;
async function warm() {
  if (warming) return;
  warming = true;
  const cache = await caches.open(CACHE);
  const have = new Set((await cache.keys()).map(r => new URL(r.url).pathname + new URL(r.url).search));
  const base = new URL(self.registration.scope).pathname;
  const todo = REST.filter(f => !have.has(base + f));
  let i = 0;
  const worker = async () => {
    while (i < todo.length) {
      const f = todo[i++];
      try { const r = await fetch(f); if (r.ok) await cache.put(f, r); } catch (e) { /* thử lại lần sau */ }
    }
  };
  // 3 luồng: tải dần ngầm, chừa băng thông cho hình bé đang xem.
  await Promise.all([worker(), worker(), worker()]);
  warming = false;
}

self.addEventListener('message', e => { if (e.data && e.data.type === 'warm') warm(); });

// Mở app: lấy trang mới từ mạng (chờ tối đa 1,5 giây), mạng chậm hoặc mất mạng thì dùng bản đã lưu của chính phiên bản này.
// Trang mới tự tải file JS/CSS đúng phiên bản nên không cần tải lại trang (trước đây tải lại làm bé bị đá ra màn Bắt đầu).
async function navigate(req) {
  const cache = await caches.open(CACHE);
  const fresh = fetch(req, {cache: 'no-store'}).then(r => {
    if (r.ok) cache.put('./', r.clone());
    return r;
  });
  const cached = await cache.match('./');
  if (!cached) return fresh.catch(() => caches.match('./'));
  const timeout = new Promise(res => setTimeout(() => res(null), 1500));
  const r = await Promise.race([fresh.catch(() => null), timeout]);
  return r && r.ok ? r : cached;
}

self.addEventListener('fetch', e => {
  if (e.request.method !== 'GET') return;
  const url = new URL(e.request.url);
  if (url.origin !== location.origin) return;
  if (url.pathname.startsWith('/api/')) return;  // đồng bộ mã gia đình: luôn đi mạng, không lưu
  if (e.request.mode === 'navigate') return e.respondWith(navigate(e.request));
  // File có ?v= phải khớp đúng phiên bản; hình và giọng đọc (tên file cố định) khớp bỏ qua query.
  const versioned = url.searchParams.has('v') && !/\/(img|audio|photo|sprites)\//.test(url.pathname);
  e.respondWith(caches.match(e.request, {ignoreSearch: !versioned}).then(hit => hit || fetch(e.request).then(r => {
    if (r.ok && /\/(img|audio|photo|sprites)\//.test(url.pathname)) caches.open(CACHE).then(c => c.put(e.request, r.clone()));
    return r;
  })));
});
